import manifestJson from './manifest.json';
import type { SignClip, SignManifest } from './types';

/** Generated by scripts/build-heart-sound-library.py — do not edit by hand. */
export const SIGN_MANIFEST = manifestJson as SignManifest;
export const SIGN_CLIPS: SignClip[] = SIGN_MANIFEST.clips;

export type SignDeck = 'all' | 'adult' | 'murmur';
export const SIGN_DECKS: { id: SignDeck; title: string; description: string }[] = [
  { id: 'all', title: 'Mixed', description: 'Every clip in the library.' },
  { id: 'adult', title: 'Adult valve lesions', description: 'Adults with aortic stenosis, mitral regurgitation, or normal controls (PhysioNet 2016).' },
  { id: 'murmur', title: 'Murmur characterisation', description: 'Children and adolescents with expert murmur annotations (CirCor DigiScope).' },
];

export function clipsForDeck(deck: SignDeck, clips: SignClip[] = SIGN_CLIPS): SignClip[] {
  if (deck === 'adult') return clips.filter(c => c.source === 'physionet-2016');
  if (deck === 'murmur') return clips.filter(c => c.source === 'circor-2022');
  return clips;
}
